function openPhotoContext(id,x,y){const n=byId(id);if(!n)return;state.contextNode=id;selectPhoto(id);$('photoComposer').hidden=true;const menu=$('photoContext');menu.hidden=false;menu.style.left=Math.max(8,Math.min(innerWidth-228,x-150))+'px';menu.style.top=Math.max(8,Math.min(innerHeight-345,y))+'px';menu.querySelector('[data-photo-action="make-main"]').hidden=id===state.hero||!nodeAsset(n);menu.querySelector('[data-photo-action="3d"]').hidden=!nodeAsset(n)||!!nodeAsset(n)?.mime?.startsWith('video/');menu.querySelector('[data-photo-action="video-preview"]').hidden=!nodeAsset(n)?.mime?.startsWith('video/');}
