function contextPrompt(type){return ({describe:'Describe the visible objects, materials, physical geometry and possible separable components. Mark uncertainties.',video:'Create a six-shot storyboard and filming/motion prompt for a video based on this image; this is a PLAN, not a rendered video.',avatar:'Propose an original 3D avatar and rigging plan based on visible clothing and shape. Explain topology, joints, animation requirements and uncertainty. This is a PLAN, not a generated avatar.',persona:'Create a FICTIONAL character profile inspired by the scene; no claims about the real person in the photo, including identity, age or private traits.'})[type]||'';}
function openComposer(type){const n=byId(state.contextNode||state.selected);if(!n||!nodeAsset(n)){notify('Select a saved image.');return;}$('photoContext').hidden=true;state.composerAction=type;const box=$('photoComposer');box.hidden=false;$('composerPrompt').hidden=false;$('composerProvider').hidden=false;$('composerSend').hidden=false;const label={describe:'Describe / ask image AI',image:'Transform image',video:'Video storyboard plan',avatar:'Avatar / rig plan',persona:'Fictional persona concept'}[type]||'Ask AI';$('composerTitle').textContent=label;$('composerSource').textContent='Source · '+n.label;$('composerPrompt').value=contextPrompt(type);$('composerResult').hidden=true;$('composerResult').textContent='';const select=$('composerProvider');const previous=select.value;select.replaceChildren();const ready=type==='image'?state.providers.filter(isReady):readyVisionProviders();for(const provider of ready)select.add(new Option(provider.name+' · '+(type==='image'?provider.image_model:provider.model),provider.id));if(ready.some(p=>p.id===previous))select.value=previous;else if(ready.some(p=>p.id===$('imageProvider').value))select.value=$('imageProvider').value;else if(!ready.length)select.add(new Option('Connect a compatible model in Workspace',''));const menu=$('photoContext'),x=parseFloat(menu.style.left)||15,y=parseFloat(menu.style.top)||90;box.style.left=Math.max(8,Math.min(innerWidth-385,x))+'px';box.style.top=Math.max(8,Math.min(innerHeight-310,y+30))+'px';box.hidden=false;}
function openVideoPreview(n){const a=nodeAsset(n);if(!a?.mime?.startsWith('video/'))return;$('videoStageTitle').textContent=n.label||'Video';$('videoStagePlayer').src=a.url;$('videoStage').hidden=false;$('videoStagePlayer').play().catch(()=>{});}
async function showPhotoDocuments(){const n=byId(state.contextNode||state.selected),a=nodeAsset(n);if(!a||!state.project)return;$('photoContext').hidden=true;const box=$('photoComposer');box.hidden=false;state.composerAction='documents';$('composerTitle').textContent='Image documents';$('composerSource').textContent='Source · '+n.label;$('composerPrompt').hidden=true;$('composerProvider').hidden=true;$('composerSend').hidden=true;const root=$('composerResult');root.hidden=false;root.replaceChildren();root.textContent='Loading stored descriptions…';try{const r=await api('projects/'+state.project.id+'/assets/'+a.id+'/documents');root.replaceChildren();if(!r.documents?.length){root.textContent='No saved descriptions yet. Use Describe / ask image AI to create one.';return;}for(const d of r.documents){const entry=document.createElement('div');entry.className='doc-entry';const heading=document.createElement('small');heading.textContent=`${d.kind} · ${d.provider||'UMI'} · ${d.model||''} · ${new Date(d.created_at*1000).toLocaleString()}`;const text=document.createElement('pre');text.textContent=(d.prompt?'Prompt: '+d.prompt+'\n\n':'')+d.content;const copy=document.createElement('button');copy.textContent='Copy';copy.onclick=()=>navigator.clipboard.writeText(text.textContent).then(()=>notify('Document copied'));entry.append(heading,text,copy);root.append(entry);}}catch(e){root.textContent=e.message;}const x=parseFloat($('photoContext').style.left)||22,y=parseFloat($('photoContext').style.top)||90;box.style.left=Math.min(innerWidth-400,Math.max(8,x))+'px';box.style.top=Math.min(innerHeight-340,Math.max(8,y))+'px';}
async function runPhotoAction(){const node=byId(state.contextNode),asset=nodeAsset(node);const text=$('composerPrompt').value.trim();const providerId=$('composerProvider').value;const type=state.composerAction;if(!node||!asset||!state.project)return;if(!text){$('composerPrompt').focus();return;}if(!providerId){openDrawer('models');notify('Choose a compatible model in Workspace → Models');return;}
 const button=$('composerSend');button.disabled=true;button.textContent='Working…';$('composerResult').hidden=false;$('composerResult').textContent='Contacting '+providerId+'…';try{if(type==='image'){const r=await api('concepts/generate',{method:'POST',json:{project_id:state.project.id,provider_id:providerId,mode:'variation',prompt:'Use this exact source image',instructions:text,reference_ids:[asset.id],source_asset_id:asset.id,subject_type:node.subjectType||state.subjectType,temp_provider:state.tempKeys[providerId]||null}});const a=r.assets[0];const spot=Layout.nextFreeSpot(state.nodes,{x:node.x+350,y:node.y+215},'source',state.hero);appendNode(a,'source','Variation · '+node.label,node.id,spot);await commitHistory('Image variation');$('photoComposer').hidden=true;notify('Variation saved next to the source image.');}else{const r=await api('projects/'+state.project.id+'/visual-query',{method:'POST',json:{asset_id:asset.id,provider_id:providerId,prompt:text,temp_provider:state.tempKeys[providerId]||null}});$('composerResult').textContent=r.answer;const notes=node.aiNotes||[];notes.push({type,prompt:text,answer:r.answer,provider:providerId,at:new Date().toISOString()});node.aiNotes=notes.slice(-4).map(item=>({...item,answer:item.answer.slice(0,1500)}));await commitHistory('AI '+type+' note');}}catch(e){$('composerResult').textContent='Unable to complete: '+e.message;notify(e.message);}finally{button.disabled=false;button.textContent='Run ↗';}}
function handlePhotoAction(action){const id=state.contextNode,n=byId(id);$('photoContext').hidden=true;if(!n)return;switch(action){case 'make-main':makeMain(id);break;case 'analyze':selectPhoto(id);analyzeCurrent().catch(e=>notify(e.message));break;case '3d':selectPhoto(id);createMesh().catch(e=>notify(e.message));break;case 'documents':showPhotoDocuments().catch(e=>notify(e.message));break;case 'video-preview':openVideoPreview(n);break;case 'copy':state.multi.clear();state.multi.add(id);duplicateSelection();break;case 'pack':state.multi.clear();state.multi.add(id);markSelection();$('selectionBar').hidden=false;break;case 'archive':archiveNodeIds([id]);break;default:openComposer(action);}}
