 const finish=e=>{const d=state.drag;if(!d)return;state.drag=null;$('board').classList.remove('grabbing');if(d.kind==='marquee'){const a=screenToWorld(d.x,d.y),b=screenToWorld(e.clientX,e.clientY);$('marquee').hidden=true;const minX=Math.min(a.x,b.x),maxX=Math.max(a.x,b.x),minY=Math.min(a.y,b.y),maxY=Math.max(a.y,b.y);if(!d.extend)state.multi.clear();for(const n of visibleNodes()){const sz=Layout.extent(n,state.hero);if(n.x+sz.w/2>=minX&&n.x-sz.w/2<=maxX&&n.y+sz.h/2>=minY&&n.y-sz.h/2<=maxY)state.multi.add(n.id);}state.selected=[...state.multi][0]||null;markSelection();showEmpty();}else if(Math.abs(d.x-e.clientX)+Math.abs(d.y-e.clientY)>5){commitHistory('Move canvas view').catch(()=>{});}if($('board').hasPointerCapture(e.pointerId))$('board').releasePointerCapture(e.pointerId);};$('board').addEventListener('pointerup',finish);$('board').addEventListener('pointercancel',finish);
